[Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)
$OutputEncoding = [Console]::OutputEncoding
$ErrorActionPreference = "Stop"
Set-Location -LiteralPath $PSScriptRoot
$currentVersion = ([IO.File]::ReadAllText((Join-Path $PSScriptRoot 'VERSION.txt'),[Text.Encoding]::UTF8)).Trim()
$script:AuditErrors = New-Object System.Collections.Generic.List[string]
function Audit-Fail([string]$Message) {
    $script:AuditErrors.Add($Message) | Out-Null
    Write-Host "ERROR $Message" -ForegroundColor Red
}
function Read-Utf8([string]$Path) {
    if ([string]::IsNullOrWhiteSpace($Path)) { Audit-Fail "Ruta vacia al leer archivo"; return "" }
    if (-not (Test-Path -LiteralPath $Path)) { Audit-Fail "Falta archivo: $Path"; return "" }
    try { return [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8) }
    catch { Audit-Fail "No se pudo leer $Path : $($_.Exception.Message)"; return "" }
}
function Require-Text([string]$Path, [string]$Text, [string]$Description) {
    if ([string]::IsNullOrWhiteSpace($Path)) { Audit-Fail "Ruta vacia al verificar: $Description"; return }
    if (-not (Test-Path -LiteralPath $Path)) { Audit-Fail "Falta archivo para requisito: $Description -> $Path"; return }
    $content = Read-Utf8 $Path
    if ($content.IndexOf($Text, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) { Audit-Fail "No se encontro requisito: $Description"; return }
    Write-Host "OK  $Description" -ForegroundColor Green
}
function Forbid-Text([string]$Path, [string]$Text, [string]$Description) {
    if ([string]::IsNullOrWhiteSpace($Path)) { Audit-Fail "Ruta vacia al verificar: $Description"; return }
    if (-not (Test-Path -LiteralPath $Path)) { Audit-Fail "Falta archivo para restriccion: $Description -> $Path"; return }
    $content = Read-Utf8 $Path
    if ($content.IndexOf($Text, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { Audit-Fail "Se encontro acceso/texto que debe estar bloqueado: $Description"; return }
    Write-Host "OK  $Description" -ForegroundColor Green
}
