$allowedRoutes = @('/app/dashboard','/app/recepcion-hoy','/app/pacientes','/app/paciente-360','/app/citas','/app/agenda-diaria','/app/tratamientos-proformas','/app/mapa-sillones','/app/solicitudes-web','/app/caja-pagos','/app/satisfaccion','/app/laboratorio','/app/reportes','/app/reclamos','/app/inventario')
foreach($route in $allowedRoutes){ Require-Text $guards $route "Recepcion: ruta permitida $route"; Require-Text $shell $route "Recepcion: acceso visible permitido $route" }
$blockedReceptionRoutes = @('/app/atenciones','/app/emergencias','/app/presupuestos','/app/documentos','/app/membresias','/app/seguimientos','/app/esterilizacion','/app/tratamientos','/app/finanzas','/app/usuarios','/app/recursos-agenda','/app/analisis-sillones','/app/gobierno')
foreach($route in $blockedReceptionRoutes){
    $needle = if($route -eq '/app/tratamientos') { "'/app/tratamientos'" } else { $route }
    Forbid-Text $guards $needle "Recepcion: ruta excluida de lista blanca $route"
}
$shellContent = Read-Utf8 $shell
$menuWhitelistMatch = [regex]::Match($shellContent, '(?s)receptionAllowedRoutes\s*=\s*new Set\(\[(.*?)\]\);')
if (-not $menuWhitelistMatch.Success) {
    Audit-Fail "No se pudo localizar la lista blanca de menu de Recepcion"
    $menuWhitelist = ""
} else {
    $menuWhitelist = $menuWhitelistMatch.Groups[1].Value
}
$menuBlockedFound = $false
foreach($route in $blockedReceptionRoutes){
    $exactRoute = "'" + $route + "'"
    if($menuWhitelist.IndexOf($exactRoute,[System.StringComparison]::OrdinalIgnoreCase) -ge 0){ Audit-Fail "Recepcion tiene acceso no permitido en menu: $route"; $menuBlockedFound = $true }
}
if($menuWhitelistMatch.Success -and -not $menuBlockedFound){ Write-Host "OK  Recepcion: menu limitado exclusivamente a los accesos autorizados" -ForegroundColor Green }
