if ($mysqlStartIndex -lt 0 -or $eurekaStartIndex -lt 0) {
    Audit-Fail "No se encontraron las etapas MySQL/Eureka en el iniciador local"
} elseif ($mysqlStartIndex -ge $eurekaStartIndex) {
    Audit-Fail "Orden de arranque invalido: MySQL debe iniciar antes que Eureka"
} else {
    Write-Host "OK  Docker local: MySQL arranca antes que Eureka y el inicio es escalonado" -ForegroundColor Green
}
