Require-Text $buildClassifier "COMPILATION ERROR" "Diagnostico futuro: clasifica errores Java/Maven"
Require-Text $buildClassifier "no space left on device" "Diagnostico futuro: clasifica falta de espacio"
Require-Text $buildClassifier "grpc server closed unexpectedly" "Diagnostico futuro: clasifica caidas de BuildKit/gRPC"
Require-Text $buildClassifier "failed to read dockerfile" "Diagnostico futuro: clasifica Dockerfile/ruta de build incorrecta"
Require-Text $buildClassifier "unable to prepare context" "Diagnostico futuro: clasifica contexto/ruta Docker de Windows invalida"

Require-Text $buildValidator '"%~dp0docker\Dockerfile.runtime.local"' "Build futuro: Dockerfile runtime usa ruta explicita y no depende del contexto"
Forbid-Text $buildValidator ' -f Dockerfile -t ' "Build futuro: no reaparece Dockerfile relativo que fallo en Windows"
Require-Text $containerEnsure "@('compose','create','--no-build','--pull','never')" "Contenedores: crea automaticamente los faltantes sin recompilar"
Require-Text $containerEnsure 'Contenedores=17/17' "Contenedores: verifica los 17 esperados despues de crear"
Require-Text (Join-Path $PSScriptRoot '01-INSTALAR-O-ACTUALIZAR.bat') 'ASEGURAR-CONTENEDORES.ps1' "Instalacion: crea/verifica contenedores antes del arranque"
Require-Text (Join-Path $PSScriptRoot '02-INICIAR.bat') 'ASEGURAR-CONTENEDORES.ps1' "Uso diario: crea contenedores faltantes si las imagenes existen"
Require-Text $buildValidator "TransientOnly" "Compilacion futura: reintenta solo fallos transitorios de red"
Require-Text $diagnosticScript "CLASIFICACION AUTOMATICA DE ERRORES" "Diagnostico futuro: incorpora clasificacion automatica"
Require-Text $preflight "docker compose config --services" "Prevencion futura: preflight valida estructura real de Compose"
Require-Text $preflight "Get-NetTCPConnection" "Prevencion futura: preflight advierte conflictos de puertos"
Require-Text $preflight "JWT_SECRET" "Prevencion futura: preflight valida secretos locales requeridos"
Require-Text $preflight "POM raiz declara 16 modulos Maven" "Prevencion futura: preflight valida modulos Maven"
Require-Text $preflight "SelectNodes('/m:project/m:modules/m:module'" "Prevencion futura: modulos Maven se leen por XPath compatible con PowerShell 5.1"
Forbid-Text $preflight "project.modules.module | ForEach-Object { [string]$_.InnerText }" "Prevencion futura: no reutiliza la lectura XML que dejaba nombres de modulo vacios en PowerShell 5.1"
Require-Text $preflight 'parentGroup -ne $rootGroup' "Prevencion futura: parent Maven se valida por groupId, artifactId y version del proyecto"
Require-Text $waitScript "Save-Logs" "Diagnostico futuro: arranque conserva logs del servicio que falla"
Require-Text $waitScript "startup-logs" "Diagnostico futuro: arranque conserva logs por contenedor problematico"
Require-Text $diagnosticScript "ESTADO DETALLADO DE CONTENEDORES" "Diagnostico futuro: registra exit code, OOM y reinicios por contenedor"
Require-Text $diagnosticScript "PREVALIDACION PREVENTIVA" "Diagnostico futuro: incorpora el resultado del preflight"
Require-Text $preflight 'PowerShell seguro: no hay variables ambiguas seguidas inmediatamente por dos puntos' "Prevencion futura: preflight bloquea interpolaciones PowerShell ambiguas antes de ejecutar scripts"
Require-Text (Join-Path $PSScriptRoot 'database/mysql/init-databases.sh') 'MYSQL_PWD="${MYSQL_ROOT_PASSWORD}"' "MySQL init: evita warning de password en CLI"
Forbid-Text (Join-Path $PSScriptRoot 'database/mysql/init-databases.sh') '`auth_db`' "MySQL init: no usa backticks que /bin/sh ejecuta como comandos"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-MYSQL-INICIALIZADO.ps1') 'Repair-Initialization' "MySQL: repara inicializacion parcial de forma idempotente"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-MYSQL-INICIALIZADO.ps1') 'MYSQL_PWD=' "MySQL: validador no depende de -pPASSWORD"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-MYSQL-INICIALIZADO.ps1') 'SELECT(1)' "MySQL: prueba conexion real con SQL sin espacios ni quoting fragil"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-MYSQL-INICIALIZADO.ps1') "'--env'" "MySQL: password se pasa a docker exec como entorno, no por shell"
Forbid-Text (Join-Path $PSScriptRoot 'VERIFICAR-MYSQL-INICIALIZADO.ps1') "'sh','-lc'" "MySQL: validador no interpone shell entre PowerShell y cliente mysql"
Require-Text (Join-Path $PSScriptRoot 'PREPARAR-ENTORNO-LOCAL.ps1') 'Get-ContainerEnvironment' "Actualizacion: recupera secretos del contenedor MySQL existente"
Require-Text (Join-Path $PSScriptRoot '01-INSTALAR-O-ACTUALIZAR.bat') '-ForceRecreate' "Actualizacion: recrea contenedores con nueva configuracion preservando volumenes"
Require-Text (Join-Path $PSScriptRoot 'ASEGURAR-CONTENEDORES.ps1') '--force-recreate' "Contenedores: soporta recreacion forzada sin build"
Require-Text (Join-Path $PSScriptRoot 'docker-compose.yml') 'MYSQL_PWD="$${MYSQL_ROOT_PASSWORD}" mysqladmin ping' "MySQL healthcheck local: evita password por CLI"
Require-Text (Join-Path $PSScriptRoot 'docker-compose.production-secure.yml') 'MYSQL_PWD="$${MYSQL_ROOT_PASSWORD}" mysqladmin ping' "MySQL healthcheck produccion: evita password por CLI"
Require-Text $gatewaySessionFilter 'WebClient.builder()' "Gateway runtime: construye WebClient sin bean autoconfigurado"
Forbid-Text $gatewaySessionFilter 'WebClient.Builder builder' "Gateway runtime: no depende de WebClient.Builder ausente"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-GATEWAY-RUNTIME.ps1') 'docker-dns-auth-scope-v3' "Gateway runtime: imagen lleva marcador de hotfix verificable"
Require-Text (Join-Path $PSScriptRoot 'REPARAR-GATEWAY.bat') 'Dockerfile.gateway.repair' "Gateway runtime: reparacion dirigida reconstruye solo gateway"
Require-Text (Join-Path $PSScriptRoot 'REPARAR-GATEWAY.bat') '-f "docker/Dockerfile.gateway.repair"' "Gateway repair Windows: Dockerfile usa ruta relativa tras cd al proyecto"
Require-Text (Join-Path $PSScriptRoot 'REPARAR-GATEWAY.bat') '-t "clinica-cardenas-local-api-gateway:latest" .' "Gateway repair Windows: contexto final usa punto y evita backslash escapando comillas"
Forbid-Text (Join-Path $PSScriptRoot 'REPARAR-GATEWAY.bat') '"%~dp0" > "%~dp0build-logs\gateway-repair.log"' "Gateway repair Windows: no usa %~dp0 como contexto Docker final"
Forbid-Text (Join-Path $PSScriptRoot 'REPARAR-GATEWAY.bat') 'docker stop clinica-api-gateway' "Gateway repair segura: no detiene el Gateway antes de tener nueva imagen validada"

Require-Text $buildValidator 'pe.clinica.cardenas.gateway.runtime=docker-dns-auth-scope-v3' "Gateway runtime: build completo etiqueta hotfix"
Forbid-Text (Join-Path $PSScriptRoot 'REPARAR-GATEWAY.bat') 'COMPILAR-ACTUAL.bat' "Gateway runtime: hotfix no relanza reactor completo"
Require-Text (Join-Path $PSScriptRoot '01-INSTALAR-O-ACTUALIZAR.bat') 'REPARAR-GATEWAY.bat' "Instalacion: corrige gateway antiguo aun con 17/17 imagenes"
Require-Text $waitScript 'Get-RuntimeStatus' "Arranque futuro: detecta estado restarting ademas de health"
Require-Text $waitScript "runtime.Restarts -ge 3" "Arranque futuro: falla rapido ante bucle de reinicio"
Require-Text $waitScript 'Start-Process -FilePath' "Diagnostico futuro: captura docker logs sin NativeCommandError de PowerShell"
Require-Text (Join-Path $PSScriptRoot 'api-gateway/src/main/resources/application.yml') 'CONTENT_ROUTE_URI:lb://CONTENT-SERVICE' "Gateway local: content route soporta DNS Docker con fallback Eureka"
Require-Text (Join-Path $PSScriptRoot 'api-gateway/src/main/resources/application.yml') 'AUTH_ROUTE_URI:lb://AUTH-SERVICE' "Gateway local: auth route soporta DNS Docker con fallback Eureka"
Require-Text (Join-Path $PSScriptRoot 'docker-compose.yml') 'CONTENT_ROUTE_URI: http://content-service:8089' "Gateway local: content-service usa DNS Docker directo"
Require-Text (Join-Path $PSScriptRoot 'docker-compose.yml') 'PATIENT_ROUTE_URI: http://patient-service:8082' "Gateway local: patient-service usa DNS Docker directo"
Require-Text (Join-Path $PSScriptRoot 'docker-compose.yml') 'SPRING_CLOUD_DISCOVERY_ENABLED: "false"' "Gateway local: DiscoveryClient desactivado porque las rutas usan DNS Docker"
Require-Text (Join-Path $PSScriptRoot 'docker-compose.yml') 'AUTH_VALIDATION_TIMEOUT_SECONDS: "10"' "Gateway local: timeout auth separado y tolerante a picos de Windows/Docker"
Require-Text (Join-Path $PSScriptRoot 'docker-compose.production-secure.yml') 'AUTH_VALIDATION_TIMEOUT_SECONDS: "3"' "Gateway produccion: timeout auth estricto y explicito"
Require-Text $gatewaySessionFilter 'Retry.max(1)' "Gateway: validacion auth reintenta una sola vez fallos transitorios"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-GATEWAY-RUNTIME.ps1') 'docker-dns-auth-scope-v3' "Gateway runtime: marcador de ruteo Docker directo"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-RUTEO-LOCAL.ps1') 'CONTENT_DIRECTO' "Validacion runtime: prueba content-service directo"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-RUTEO-LOCAL.ps1') 'CONTENT_VIA_GATEWAY' "Validacion runtime: compara contenido via Gateway"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-RUTEO-LOCAL.ps1') 'RutasDockerDirectas=13/13' "Validacion runtime: exige las 13 URI locales directas"
Require-Text (Join-Path $PSScriptRoot '07-REPARAR-RUTEO-Y-VALIDAR.bat') '--force-recreate api-gateway frontend' "Hotfix ruteo: recrea solo Gateway + frontend para renovar DNS"
Forbid-Text (Join-Path $PSScriptRoot '07-REPARAR-RUTEO-Y-VALIDAR.bat') 'docker compose create --force-recreate' "Hotfix ruteo: no recrea los 17 contenedores"

Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-RUTEO-LOCAL.ps1') 'Assert-HomeContract' "Ruteo local: valida contrato JSON por estructura y no por texto acentuado literal"
Forbid-Text (Join-Path $PSScriptRoot 'VERIFICAR-RUTEO-LOCAL.ps1') '$direct.clinic -ne' "PowerShell 5.1: ruteo no compara literalmente texto UTF-8 con tildes"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-RUTEO-LOCAL.ps1') 'ERROR_CONTRATO_DESTINO' "Ruteo local: diferencia contrato invalido de servicio caido y de fallo Gateway"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-BACKUP-LOCAL.ps1') 'http://localhost:8094/actuator/health' "Backup local: valida health HTTP real"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-BACKUP-LOCAL.ps1') 'docker compose up' "Backup local: puede levantar el modulo si estaba detenido"
Require-Text (Join-Path $PSScriptRoot 'VERIFICAR-BACKUP-LOCAL.ps1') 'ConvertFrom-Json' "Backup local: inspecciona estado Docker por JSON compatible con PowerShell 5.1"
Require-Text (Join-Path $PSScriptRoot 'INICIAR-OPTIMIZADO.ps1') "'backup-service'='clinica-backup-service'" "Arranque local: backup-service forma parte del grupo healthy obligatorio"
Forbid-Text (Join-Path $PSScriptRoot 'INICIAR-OPTIMIZADO.ps1') '& docker stop clinica-backup-service' "Arranque local: no oculta fallos de Backup deteniendolo y declarando exito"
Require-Text (Join-Path $PSScriptRoot '06-VALIDAR-SISTEMA.bat') 'VERIFICAR-BACKUP-LOCAL.ps1' "Validacion repetible: exige Backup antes de la suite funcional"
Require-Text (Join-Path $PSScriptRoot '07-REPARAR-RUTEO-Y-VALIDAR.bat') 'GATEWAY_REPAIRED' "Hotfix ruteo: no recrea Gateway si el runtime y ruteo ya son correctos"
Require-Text (Join-Path $PSScriptRoot '07-REPARAR-RUTEO-Y-VALIDAR.bat') 'VERIFICAR-BACKUP-LOCAL.ps1' "Hotfix ruteo: recupera Backup antes de las pruebas"
Require-Text (Join-Path $PSScriptRoot '08-VALIDAR-FINAL.bat') 'VERIFICAR-RUTEO-LOCAL.ps1' "Validacion final: comprueba ruteo sin recompilar"
Require-Text (Join-Path $PSScriptRoot '08-VALIDAR-FINAL.bat') 'VERIFICAR-BACKUP-LOCAL.ps1' "Validacion final: comprueba Backup"
Forbid-Text (Join-Path $PSScriptRoot '08-VALIDAR-FINAL.bat') 'docker build' "Validacion final: no construye imagenes"
Forbid-Text (Join-Path $PSScriptRoot '08-VALIDAR-FINAL.bat') 'mvn ' "Validacion final: no ejecuta Maven"
Forbid-Text (Join-Path $PSScriptRoot '08-VALIDAR-FINAL.bat') 'npm ' "Validacion final: no ejecuta NPM"
Forbid-Text (Join-Path $PSScriptRoot '08-VALIDAR-FINAL.bat') '--force-recreate' "Validacion final: no recrea contenedores sanos"
Require-Text (Join-Path $PSScriptRoot '05-GENERAR-DIAGNOSTICO.ps1') 'VALIDACION BACKUP LOCAL' "Diagnostico: incorpora estado y log del modulo Backup"

if($script:AuditErrors.Count -gt 0){
    Write-Host ""
    Write-Host "AUDITORIA COMPLETA: $($script:AuditErrors.Count) error(es) encontrados." -ForegroundColor Red
    foreach($err in $script:AuditErrors){ Write-Host " - $err" -ForegroundColor Red }
    exit 1
}

Write-Host "TODOS LOS REQUISITOS ESTATICOS Y LA LISTA BLANCA DE RECEPCION ESTAN PRESENTES." -ForegroundColor Green
Write-Host "AUDITORIA COMPLETA: 0 errores." -ForegroundColor Green
exit 0
